    /// edges of such files at alpha 0.
    static func checkAlphaSurvivesTheSize(
        _ settings: ExportSettings, canvas: CGSize
    ) throws {
        guard settings.alpha, canvas.width >= 1, canvas.height >= 1,
            settings.width >= 1, settings.height >= 1
        else { return }
